-- Agri-Rescue reference/lookup data seed.
--
-- The university DB was created from docs/database/schema.sql, which only
-- inserts a handful of sample rows -- it does not include the reference
-- catalog data that the app's migrations (server/src/db/migrations) and
-- seed script (server/src/db/seed.ts) populate on a dev install.
--
-- This file:
--   1. Clears ALL Agri-Rescue tables (children first) so the sample rows
--      from schema.sql are removed and there are no ID clashes or orphan
--      rows pointing at the old sample crops. It does NOT touch the other
--      project's tables sharing this database (categories, group_products,
--      products, product_stores, stock_movements, stores, inventory_users,
--      schema_migrations).
--   2. Re-inserts the reference/lookup data only (crop_categories, crops,
--      crop_season_factors, crop_reference_prices) as dumped from a local
--      dev install of agri_rescue. No user-generated data (users, plots,
--      harvest_lots, orders, notifications, etc.) is included.
--
-- Import via phpMyAdmin against the existing university schema (schema.sql
-- must already be loaded). Safe to re-run.

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- 1. Clear existing Agri-Rescue rows (children before parents; FK checks are
--    off above so order is for hygiene, not correctness).
DELETE FROM support_attachments;
DELETE FROM support_messages;
DELETE FROM support_tickets;
DELETE FROM impact_logs;
DELETE FROM donation_infractions;
DELETE FROM donation_proofs;
DELETE FROM route_stops;
DELETE FROM payments;
DELETE FROM orders;
DELETE FROM batches;
DELETE FROM quality_assessments;
DELETE FROM lot_delete_logs;
DELETE FROM lot_edit_logs;
DELETE FROM lot_photos;
DELETE FROM harvest_lots;
DELETE FROM dit_mapping_suggestions;
DELETE FROM plots;
DELETE FROM shop_follows;
DELETE FROM shops;
DELETE FROM notifications;
DELETE FROM crop_reference_prices;
DELETE FROM crop_season_factors;
DELETE FROM crops;
DELETE FROM crop_categories;
DELETE FROM org_review_logs;
DELETE FROM org_application_docs;
DELETE FROM buyer_profiles;
DELETE FROM users;

ALTER TABLE crop_categories AUTO_INCREMENT = 1;
ALTER TABLE crops AUTO_INCREMENT = 1;
ALTER TABLE crop_season_factors AUTO_INCREMENT = 1;
ALTER TABLE crop_reference_prices AUTO_INCREMENT = 1;

-- 2. Reference data (data-only, dumped from local dev DB agri_rescue).


SET FOREIGN_KEY_CHECKS = 1;
